// Prototype A presentation, retaining the validated request and payment workflow.
const aNames={'Home':'Dashboard','All requests':'Reimbursements','Emails':'Email Center'};
go=function(v){view=aNames[v]||v;selected=null;render();window.scrollTo(0,0);};
sidebar=function(){const r=current(),navs=[['Dashboard','⌂'],['Reimbursements','▤'],['Auto-Updater','↻'],['Email Center','✉'],['Requirements Checker','☑'],['Reports','▥'],['Settings','⚙']];return `<div class="brand"><img src="logo.png" alt="RMC2 Consultancy Corporation"><div><strong>RMC2</strong><small>CONSULTANCY CORP</small></div></div><p class="product">Reimbursement Monitor</p><nav aria-label="Main navigation">${navs.map(([v,icon])=>`<button class="${view===v||view==='Request'&&v==='Reimbursements'?'active':''}" onclick="go('${v}')"><span class="icon" aria-hidden="true">${icon}</span>${v}</button>`).join('')}</nav>${r?`<section class="steps"><p class="navlabel">Request progress</p><nav aria-label="Request progress">${['Review request','Prepare email','Replies & decision','Payment'].map((s,i)=>`<button onclick="setStep(${i+1})" class="${step===i+1?'active':''}" ${step===i+1?'aria-current="step"':''}><span class="stepnum">${i+1}</span><span>${s}<small>${stepState(r,i+1)}</small></span></button>`).join('')}${button('Activity & notes',"step=5;render()",step===5?'active':'')}</nav></section>`:''}<div class="asidebottom"><small>Single-user demo</small><a href="compare.html">Compare preserved designs</a>${button('Reset demo','resetDialog()','quiet')}</div>`;};
home=function(){const stats=[['New request','New requests','new-request'],['Missing requirements','Missing requirements','lacking'],['Processing','Processing','processing'],['Paid','Paid','paid']];const attention=records.filter(r=>!['Paid','Denied'].includes(r.status));return `<div class="heading"><div><h1>Dashboard</h1><p class="muted">Your reimbursement workspace.</p></div>${button('Add sample request',"go('New sample')",'primary')}</div><div class="stats">${stats.map(([s,l,c])=>`<button class="stat stat-${c}" onclick="statusFilter='${s}';go('Reimbursements')"><span>${l}</span><strong>${records.filter(r=>s==='Processing'?['Under review','Awaiting reply','Approved · unpaid'].includes(r.status):r.status===s).length}</strong><em>View requests</em></button>`).join('')}</div>${totals()}<section class="panel flush"><div class="toolbar row between"><h2>Needs attention <span class="attention-count">${attention.length}</span></h2>${button('View all',"statusFilter='All';go('Reimbursements')",'quiet')}</div>${requestTable(attention)}</section><div class="twocol"><section class="panel"><h3>Today’s follow-ups</h3>${records.filter(r=>r.followup&&r.followup<=TODAY&&!['Paid','Denied'].includes(r.status)).map(r=>`<div class="event"><strong>${esc(r.name)}</strong><small>${r.id} · ${date(r.followup)}</small>${button('View conversation',`openCase('${r.id}',3)`,'textlink')}</div>`).join('')||'<p class="muted">No follow-ups due.</p>'}</section><section class="panel"><h3>Recent activity</h3>${records.flatMap(r=>r.history.slice(0,1).map(e=>({...e,id:r.id}))).sort((a,b)=>b.at.localeCompare(a.at)).slice(0,3).map(e=>`<div class="event">${esc(e.text)}<small>${e.id} · ${time(e.at)}</small></div>`).join('')}</section></div><div class="note">Prototype A · fictional records and emails · ${date(TODAY)}. Changes reset when you reload.</div>`;};
const aList=list,aEmails=emails,aFiltered=filtered;
filtered=function(){if(statusFilter!=='Processing')return aFiltered();const previous=statusFilter;statusFilter='All';const rows=aFiltered().filter(r=>['Under review','Awaiting reply','Approved · unpaid'].includes(r.status));statusFilter=previous;return rows;};
list=function(){return aList().replace('<h1>All requests</h1>','<h1>Reimbursements</h1>').replace('<option >All</option>','<option >All</option><option '+(statusFilter==='Processing'?'selected':'')+'>Processing</option>');};
emails=function(){return aEmails().replace('<h1>Emails</h1>','<h1>Email Center</h1>');};
function aRequirements(){return `<div class="heading"><div><h1>Requirements Checker</h1><p class="muted">Open a request to check its requirements in Step 1.</p></div></div>${requestTable(records.filter(r=>!['Paid','Denied'].includes(r.status)&&(!ready(r)||r.files.some(f=>f.replacement))))}`;}
function aUpdater(){return `<div class="heading"><div><h1>Auto-Updater</h1><p class="muted">Review matched replies and confirm financial updates.</p></div>${button(paused?'Resume demo checks':'Pause demo checks','toggleChecks()')}</div><div class="note">Demo only. ${paused?'Checks are paused.':'Sample replies can suggest updates.'} No live Gmail account is connected.</div><section class="panel"><h3>Simulate an incoming email</h3><label>Reimbursement<select id="simulationcase">${records.map(r=>`<option value="${r.id}">${esc(r.name)} · ${r.id}</option>`).join('')}</select></label>${button('Choose reply scenario',"selected=document.querySelector('#simulationcase').value;view='Request';step=3;render();replyDialog()",'primary')}</section><section class="panel"><h3>Pending confirmation</h3>${requestTable(records.filter(r=>r.proposal))}</section>`;}
render=function(){$('#sidebar').innerHTML=sidebar();$('#breadcrumb').textContent=selected?'Reimbursements / '+selected:(aNames[view]||view);const pages={'Home':home,'Dashboard':home,'All requests':list,'Reimbursements':list,'Request':detail,'Emails':emails,'Email Center':emails,'Auto-Updater':aUpdater,'Requirements Checker':aRequirements,'Reports':reports,'Settings':settingsPage,'New sample':newForm};$('#app').innerHTML=(pages[view]||home)();};
view='Dashboard';render();

